import React, { useState, useEffect } from 'react';
import CoinflipGameCard from '../components/CoinflipGameCard';
import CreateCoinflipModal from '../components/CreateCoinflipModal';
import LeaderboardModal from '../components/LeaderboardModal';
import AnimatedPopup from '../components/AnimatedPopup';
import { useAuth } from '../context/AuthContext';

const CoinflipPage = ({ socket, setBalance }) => {
  const { user } = useAuth();
  const [coinflips, setCoinflips] = useState([]);
  const [activeCount, setActiveCount] = useState(0);
  const [totalInGames, setTotalInGames] = useState(0);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [sortBy, setSortBy] = useState('newest');
  const [loading, setLoading] = useState(true);
  const [userInventory, setUserInventory] = useState([]);
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [selectedBet, setSelectedBet] = useState(null);
  const [showPopup, setShowPopup] = useState(false);
  const [popupMessage, setPopupMessage] = useState('');
  const [popupType, setPopupType] = useState('info');

  // Fetch coinflips
  useEffect(() => {
    const fetchCoinflips = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip`);
        const data = await response.json();

        setCoinflips(data.coinflips);
        setActiveCount(data.activeCount);
        setTotalInGames(data.totalInGames);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching coinflips:', error);
        setLoading(false);
      }
    };

    fetchCoinflips();

    // Listen for new coinflips
    if (socket) {
      socket.on('newCoinflip', (data) => {
        setCoinflips(prev => [data, ...prev]);
        setActiveCount(prev => prev + 1);
        setTotalInGames(prev => prev + data.totalValue);
      });

      socket.on('coinflipJoined', (data) => {
        setCoinflips(prev => 
          prev.map(cf => cf.id === data.id ? data : cf)
        );
      });

      socket.on('coinflipResult', (data) => {
        setCoinflips(prev => 
          prev.map(cf => cf.id === data.id ? data : cf)
        );
      });
    }

    return () => {
      if (socket) {
        socket.off('newCoinflip');
        socket.off('coinflipJoined');
        socket.off('coinflipResult');
      }
    };
  }, [socket]);

  // Fetch user inventory
  useEffect(() => {
    const fetchInventory = async () => {
      if (user) {
        try {
          const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/inventory/${user.id}`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            }
          });
          const data = await response.json();
          setUserInventory(data.items || []);
        } catch (error) {
          console.error('Error fetching inventory:', error);
        }
      }
    };

    fetchInventory();
  }, [user]);

  // Handle sort change
  const handleSortChange = (newSort) => {
    setSortBy(newSort);
    // In a real app, we would fetch sorted data from the server
  };


  const handleJoinBet = (bet) => {
    if (userInventory.length === 0) {
      showCustomPopup('You currently have no items in your inventory to bet with.', 'warning');
      return;
    }
    setSelectedBet(bet);
    setShowJoinModal(true);
  };

  const showCustomPopup = (message, type = 'info') => {
    setPopupMessage(message);
    setPopupType(type);
    setShowPopup(true);

    // Auto-hide after 3 seconds
    setTimeout(() => {
      setShowPopup(false);
    }, 3000);
  };

  const closePopup = () => {
    setShowPopup(false);
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading coinflips...</p>
      </div>
    );
  }

  return (
    <div className="coinflip-page">
      <div className="page-header">
        <h1>Coinflip</h1>
        <div className="page-stats">
          <span>{activeCount} Active Games</span>
          <span>{totalInGames.toLocaleString()} AMP in Games</span>
        </div>
        <div className="page-actions">
          <select 
            value={sortBy} 
            onChange={(e) => handleSortChange(e.target.value)}
            className="sort-select"
          >
            <option value="newest">Newest</option>
            <option value="oldest">Oldest</option>
            <option value="value_high">Value High to Low</option>
            <option value="value_low">Value Low to High</option>
          </select>
          <button 
            className="btn btn-secondary"
            onClick={() => setShowLeaderboard(true)}
          >
            LEADERBOARD
          </button>
          <button 
            className="btn btn-secondary"
            onClick={() => setShowHistory(true)}
          >
            HISTORY
          </button>
        </div>
      </div>

      {/* Betting area with inventory display */}
      <div className="betting-area card">
        <div className="betting-header">
          <h3>Make a Bet</h3>
        </div>

        <div className="betting-controls">
          <div className="side-selection">
            <h4>Select Side:</h4>
            <div className="side-options">
              <button 
                className={`side-btn ${selectedSide === 'heads' ? 'selected' : ''}`}
                onClick={() => setSelectedSide('heads')}
              >
                <img src="/images/heads.png" alt="Heads" onError={(e) => e.target.src='/default-side.png'} />
                <span>Heads</span>
              </button>
              <button 
                className={`side-btn ${selectedSide === 'tails' ? 'selected' : ''}`}
                onClick={() => setSelectedSide('tails')}
              >
                <img src="/images/tails.png" alt="Tails" onError={(e) => e.target.src='/default-side.png'} />
                <span>Tails</span>
              </button>
            </div>
          </div>

          <div className="inventory-display">
            <h4>Your Inventory ({userInventory.length} items):</h4>
            {userInventory.length === 0 ? (
              <p>You currently have no items</p>
            ) : (
              <div className="inventory-grid">
                {userInventory.map((item, index) => (
                  <div key={`${item.itemId}-${index}`} className="inventory-item">
                    <img
                      src={item.details?.imageUrl || '/default-item.png'}
                      alt={item.details?.name}
                      className="inventory-item-image"
                      onError={(e) => {
                        e.target.src = '/default-item.png';
                      }}
                    />
                    <div className="inventory-item-info">
                      <div className="item-name">{item.details?.name}</div>
                      <div className="item-value">{item.value?.toLocaleString()} AMP</div>
                      <div className="item-quantity">Qty: {item.quantity}</div>
                      <span className={`badge badge-${item.details?.rarity}`}>
                        {item.details?.rarity}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Current bets section */}
      <div className="current-bets-section card">
        <h3>Current Bets</h3>
        {coinflips.length === 0 ? (
          <div className="no-bets-placeholder">
            <p>No current bets</p>
          </div>
        ) : (
          <div className="coinflip-list">
            {coinflips.map(coinflip => (
              <div key={coinflip.id} className="coinflip-bet-summary">
                <div className="bet-info">
                  <div className="bet-creator">
                    <img 
                      src={coinflip.creator.avatar || `https://www.roblox.com/headshot-thumbnail/image?userId=${coinflip.creator.robloxUserId}&width=420&height=420&format=png`}
                      alt="Creator Avatar"
                      className="bet-creator-avatar"
                      onError={(e) => e.target.src='/default-avatar.png'}
                    />
                    <div className="bet-details">
                      <div className="creator-name">{coinflip.creator.displayName}</div>
                      <div className="bet-value">{coinflip.totalValue?.toLocaleString()} AMP</div>
                    </div>
                  </div>

                  <div className="bet-side">
                    <span className={`side-indicator ${coinflip.sideChosen}`}>
                      {coinflip.sideChosen}
                    </span>
                  </div>

                  <div className="bet-actions">
                    <button 
                      className="btn btn-primary"
                      onClick={() => handleJoinBet(coinflip)}
                    >
                      Join Bet
                    </button>
                  </div>
                </div>

                {/* Show participants if any */}
                {coinflip.participants && coinflip.participants.length > 0 && (
                  <div className="bet-participants">
                    {coinflip.participants.map((participant, idx) => (
                      <div key={idx} className="participant-preview">
                        <img 
                          src={participant.avatar || `https://www.roblox.com/headshot-thumbnail/image?userId=${participant.robloxUserId}&width=420&height=420&format=png`}
                          alt="Participant"
                          className="participant-avatar"
                          onError={(e) => e.target.src='/default-avatar.png'}
                        />
                        <span className="participant-side">{participant.sideChosen}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>


      {/* History Modal */}
      {showHistory && (
        <div className="modal-overlay" onClick={() => setShowHistory(false)}>
          <div className="history-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Bet History</h2>
              <button className="close-modal" onClick={() => setShowHistory(false)}>×</button>
            </div>
            <div className="modal-body">
              {coinflips.filter(cf => cf.isCompleted).length === 0 ? (
                <div className="no-history-placeholder">
                  <p>No bet history available</p>
                  <p>Place a bet to start tracking your history</p>
                </div>
              ) : (
                <div className="history-list">
                  {coinflips.filter(cf => cf.isCompleted).map((bet, index) => (
                    <div key={index} className="history-item">
                      <div className="history-bet-info">
                        <span className="bet-result">
                          {bet.winnerId === user?.id ? 'Won' : 'Lost'}
                        </span>
                        <span className="bet-amount">{bet.totalValue?.toLocaleString()} AMP</span>
                        <span className="bet-side">{bet.sideChosen}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setShowHistory(false)}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Join Bet Modal */}
      {showJoinModal && selectedBet && (
        <div className="modal-overlay" onClick={() => setShowJoinModal(false)}>
          <div className="join-bet-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Join Bet</h2>
              <button className="close-modal" onClick={() => setShowJoinModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <div className="bet-to-join">
                <h3>Joining: {selectedBet.creator.displayName}'s bet</h3>
                <p>Value: {selectedBet.totalValue?.toLocaleString()} AMP</p>
                <p>Side: {selectedBet.sideChosen}</p>
              </div>

              <div className="inventory-selection">
                <h4>Select Items to Match Bet:</h4>
                {userInventory.length === 0 ? (
                  <p>You currently have no items</p>
                ) : (
                  <div className="inventory-grid">
                    {userInventory.map((item, index) => (
                      <div key={`${item.itemId}-${index}`} className="inventory-item-selectable">
                        <img
                          src={item.details?.imageUrl || '/default-item.png'}
                          alt={item.details?.name}
                          className="inventory-item-image"
                          onError={(e) => {
                            e.target.src = '/default-item.png';
                          }}
                        />
                        <div className="inventory-item-info">
                          <div className="item-name">{item.details?.name}</div>
                          <div className="item-value">{item.value?.toLocaleString()} AMP</div>
                          <div className="item-quantity">Qty: {item.quantity}</div>
                          <span className={`badge badge-${item.details?.rarity}`}>
                            {item.details?.rarity}
                          </span>
                        </div>
                        <button 
                          className="btn btn-primary"
                          onClick={() => {
                            showCustomPopup(`Selected item: ${item.details?.name}`, 'info');
                          }}
                        >
                          Select
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setShowJoinModal(false)}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {showCreateModal && (
        <CreateCoinflipModal 
          onClose={() => setShowCreateModal(false)} 
          userId={user?.id}
          socket={socket}
          setBalance={setBalance}
          userInventory={userInventory}
        />
      )}

      {showLeaderboard && (
        <LeaderboardModal 
          isOpen={showLeaderboard} 
          onClose={() => setShowLeaderboard(false)} 
        />
      )}

      {/* Custom animated popup */}
      {showPopup && (
        <AnimatedPopup 
          message={popupMessage} 
          type={popupType} 
          onClose={closePopup}
        />
      )}
    </div>
  );
};

export default CoinflipPage;
